with roots as (insert into public.categories(slug,name,sort_order) values('data-engineering','Data Engineering',10),('ai-machine-learning','AI and Machine Learning',20),('software-engineering','Software Engineering',30),('business-intelligence-analytics','Business Intelligence and Analytics',40),('cloud-devops-reliability','Cloud, DevOps and Reliability',50),('cybersecurity','Cybersecurity',60),('business-project-roles','Business and Project Roles',70) on conflict(slug) do update set name=excluded.name returning id,slug), items(slug,name,parent_slug,sort_order) as (values('azure-data-engineering','Azure Data Engineering','data-engineering',11),('databricks','Databricks','data-engineering',12),('snowflake','Snowflake','data-engineering',13),('aws-data-engineering','AWS Data Engineering','data-engineering',14),('gcp-data-engineering','GCP Data Engineering','data-engineering',15),('etl-data-warehousing','ETL and Data Warehousing','data-engineering',16),('analytics-engineering','Analytics Engineering','data-engineering',17),('applied-ai','Applied AI','ai-machine-learning',21),('agentic-ai','Agentic AI','ai-machine-learning',22),('machine-learning-engineering','Machine Learning Engineering','ai-machine-learning',23),('nlp-llm','NLP and LLM','ai-machine-learning',24),('mlops','MLOps','ai-machine-learning',25),('backend-engineering','Backend Engineering','software-engineering',31),('frontend-engineering','Frontend Engineering','software-engineering',32),('full-stack-engineering','Full Stack Engineering','software-engineering',33),('java-engineering','Java Engineering','software-engineering',34),('dotnet-engineering','.NET Engineering','software-engineering',35),('business-intelligence','Business Intelligence','business-intelligence-analytics',41),('data-analysis','Data Analysis','business-intelligence-analytics',42),('product-analytics','Product Analytics','business-intelligence-analytics',43),('financial-analytics','Financial Analytics','business-intelligence-analytics',44),('cloud-engineering','Cloud Engineering','cloud-devops-reliability',51),('devops','DevOps','cloud-devops-reliability',52),('site-reliability-engineering','Site Reliability Engineering','cloud-devops-reliability',53),('platform-engineering','Platform Engineering','cloud-devops-reliability',54),('security-engineering','Security Engineering','cybersecurity',61),('governance-risk-compliance','Governance Risk and Compliance','cybersecurity',62),('business-analysis','Business Analysis','business-project-roles',71),('product-management','Product Management','business-project-roles',72),('project-management','Project Management','business-project-roles',73),('recruiting','Recruiting','business-project-roles',74)) insert into public.categories(slug,name,parent_id,sort_order) select i.slug,i.name,r.id,i.sort_order from items i join roots r on r.slug=i.parent_slug on conflict(slug) do update set name=excluded.name,parent_id=excluded.parent_id,sort_order=excluded.sort_order;
